steps.script:
function transform(ctx) {
  var u = ctx.vars.portal_url || "";
  var m = u.match(/[?&]ac_id=(\d+)/);
  if (!m) throw new Error("未能从门户跳转地址解析 ac_id，请把「计算深澜签名」步骤里的 ctx.vars.ac_id 改为本校固定 ac_id");
  return { ac_id: m[1] };
}

function transform(ctx) {
  var MAP = {};
  var suffix = "";
  var isp = (ctx.isp || "").trim();
  if (isp) { suffix = MAP[isp] !== undefined ? MAP[isp] : (isp.charAt(0) === "@" ? isp : ""); }
  var full = (ctx.username || "") + suffix;
  return { full_username: full, encoded_username: url_encode(full), callback: "jsonp" + Math.floor(now_ms()) };
}

function transform(ctx) {
  var acId = ctx.vars.ac_id || "1";
  var n = "200";
  var type = "1";
  var ip = ""; // GoAuthing 未传 -ip 时 anotherIP 为空串（libauth/requests.go buildChallengeParams/buildLoginParams）
  var token = ctx.vars.challenge;
  var full = ctx.vars.full_username || (ctx.username || "");
  var info = srun_info(JSON.stringify({ acid: acId, enc_ver: "srun_bx1", ip: ip, password: ctx.password, username: full }), token);
    var hmd5 = md5(ctx.password);
  var checksum = sha1(token + full + token + hmd5 + token + acId + token + ip + token + n + token + type + token + info);
  return { encoded_username: url_encode(full), encoded_password: url_encode("{MD5}" + hmd5), encoded_info: url_encode(info), checksum: checksum, ac_id: acId, n: n, protocol_type: type, login_ip: ip };
}
